CREATE TRIGGER contract_memory_entries_update BEFORE UPDATE ON memory_entries WHEN NOT ((NEW.approval IS NULL OR (1=1 OR NEW.approval IS NULL)) AND (NEW.expires_at IS NULL OR (1=1 OR NEW.expires_at IS NULL)) AND (NEW.tombstone_at IS NULL OR (1=1 OR NEW.tombstone_at IS NULL)) AND (NEW.version IS NULL OR (NEW.version >= 1))) BEGIN SELECT RAISE(ABORT,'contract constraint violation: memory_entries'); END;
CREATE TEMP TABLE contract_check_evaluations(valid INTEGER);
CREATE TEMP TRIGGER validate_evaluations BEFORE INSERT ON contract_check_evaluations WHEN NEW.valid<>1 BEGIN SELECT RAISE(ABORT,'contract constraint migration: invalid existing evaluations'); END;
INSERT INTO contract_check_evaluations SELECT CASE WHEN (version IS NULL OR (version >= 1)) THEN 1 ELSE 0 END FROM evaluations;
DROP TABLE contract_check_evaluations;
CREATE TRIGGER contract_evaluations_insert BEFORE INSERT ON evaluations WHEN NOT ((NEW.version IS NULL OR (NEW.version >= 1))) BEGIN SELECT RAISE(ABORT,'contract constraint violation: evaluations'); END;
CREATE TRIGGER contract_evaluations_update BEFORE UPDATE ON evaluations WHEN NOT ((NEW.version IS NULL OR (NEW.version >= 1))) BEGIN SELECT RAISE(ABORT,'contract constraint violation: evaluations'); END;
