CREATE TEMP TRIGGER validate_model_calls BEFORE INSERT ON contract_check_model_calls WHEN NEW.valid<>1 BEGIN SELECT RAISE(ABORT,'contract constraint migration: invalid existing model_calls'); END;
INSERT INTO contract_check_model_calls SELECT CASE WHEN (purpose IS NULL OR (purpose = 'normalize' OR purpose = 'plan' OR purpose = 'resolve_action' OR purpose = 'generate_code' OR purpose = 'analyze' OR purpose = 'heal')) AND (provider IS NULL OR (length(provider) >= 1 AND length(provider) <= 200)) AND (model IS NULL OR (length(model) >= 1 AND length(model) <= 200)) AND (latency IS NULL OR (latency >= 0)) AND (outcome IS NULL OR (outcome = 'success' OR outcome = 'invalid' OR outcome = 'failed' OR outcome = 'cancelled')) AND (version IS NULL OR (version >= 1)) THEN 1 ELSE 0 END FROM model_calls;
DROP TABLE contract_check_model_calls;
