CREATE TRIGGER contract_model_calls_update BEFORE UPDATE ON model_calls WHEN NOT ((NEW.purpose IS NULL OR (NEW.purpose = 'normalize' OR NEW.purpose = 'plan' OR NEW.purpose = 'resolve_action' OR NEW.purpose = 'generate_code' OR NEW.purpose = 'analyze' OR NEW.purpose = 'heal')) AND (NEW.provider IS NULL OR (length(NEW.provider) >= 1 AND length(NEW.provider) <= 200)) AND (NEW.model IS NULL OR (length(NEW.model) >= 1 AND length(NEW.model) <= 200)) AND (NEW.latency IS NULL OR (NEW.latency >= 0)) AND (NEW.outcome IS NULL OR (NEW.outcome = 'success' OR NEW.outcome = 'invalid' OR NEW.outcome = 'failed' OR NEW.outcome = 'cancelled')) AND (NEW.version IS NULL OR (NEW.version >= 1))) BEGIN SELECT RAISE(ABORT,'contract constraint violation: model_calls'); END;
